import { useCallback, useMemo } from 'react';
import { useLocation, useNavigate } from 'ra-core';
/**
 * Stopgap: delete it if ra-core ever exposes its own useSearchParams.
 */
export const useSearchParams = () => {
    const location = useLocation();
    const navigate = useNavigate();
    const searchParams = useMemo(() => new URLSearchParams(location.search), [location.search]);
    const setSearchParams = useCallback((init, options) => {
        const search = new URLSearchParams(init ?? '').toString();
        navigate({
            pathname: location.pathname,
            search: search ? `?${search}` : '',
        }, options);
    }, [navigate, location.pathname]);
    return [searchParams, setSearchParams];
};
