import { useEffect, useCallback } from 'react';
import { useDataProvider, useEvent } from 'ra-core';
/**
 * Subscribe to the events from a topic on mount (and unsubscribe on unmount).
 *
 * @param {string} topic The topic to subscribe to
 * @param {SubscriptionCallback<RecordEvent>} callback The callback to call when an event is received on the topic
 * @param {UseSubscribeOptions} options Options object
 * @param options.enabled Whether to subscribe or not. Defaults to true
 * @param options.once Whether to unsubscribe after the first event. Defaults to false
 * @param options.unsubscribeOnUnmount Whether to unsubscribe on unmount. Defaults to true
 *
 * @example
 * import { useState } from 'react';
 * import { Badge, Typography } from '@mui/material';
 * import { useSubscribe } from '@react-admin/ra-core-ee';
 *
 * const ChannelName = ({ name }) => {
 *     const [nbMessages, setNbMessages] = useState(0);
 *     useSubscribe(`messages/${name}`, (event) => {
 *         if(event.type === 'created') {
 *             setNbMessages(count => count + 1);
 *         }
 *     });
 *     return nbMessages > 0 ? (
 *         <Badge badgeContent={nbMessages} color="primary">
 *             <Typography># {name}</Typography>
 *         </Badge>
 *     ) : (
 *        <Typography># {name}</Typography>
 *     );
 * };
 *
 * @example // unsubscribe when receiving a specific event
 * import { useState, useCallback } from 'react';
 * import { LinearProgress } from '@mui/material';
 * import { useSubscribe } from '@react-admin/ra-core-ee';
 *
 * const JobProgress = ({ jobId }) => {
 *     const [progress, setProgress] = useState(0);
 *     const [color, setColor] = useState('primary');
 *     const callback = useCallback(
 *         (event, unsubscribe) => {
 *             if (event.type === 'progress') {
 *                 setProgress(event.payload.progress);
 *             }
 *             if (event.type === 'completed') {
 *                 setColor('success');
 *                 unsubscribe();
 *             }
 *         },
 *         [setColor]
 *     );
 *     useSubscribe(`jobs/${jobId}`, callback);
 *     return (
 *         <LinearProgress
 *             variant="determinate"
 *             value={progress}
 *             color={color}
 *         />
 *     );
 * };
 *
 * @example // subscribe once
 * import { useState } from 'react';
 * import { useSubscribe } from '@react-admin/ra-core-ee';
 *
 * const OfficeClosed = () => {
 *     const [state, setState] = useState('closed');
 *
 *     useSubscribe('office/restart', () => setState('open'), { once: true });
 *
 *     return (
 *         <div>
 *             {state === 'closed'
 *                 ? 'Sorry, the office is closed for maintenance.'
 *                 : 'Welcome! The office is open.'}
 *         </div>
 *     );
 * };
 */
export const useSubscribe = (topic, callback, options) => {
    const dataProvider = useDataProvider();
    const { once = false, enabled = true, unsubscribeOnUnmount = true, } = options || {};
    const stableCallback = useEvent(callback);
    const callbackWithUnsubscribe = useCallback(event => {
        if (!topic)
            return;
        const unsubscribe = () => dataProvider.unsubscribe(topic, callbackWithUnsubscribe);
        stableCallback(event, unsubscribe);
        if (once) {
            unsubscribe();
        }
    }, [stableCallback, dataProvider, topic, once]);
    useEffect(() => {
        if (!enabled || !dataProvider || !topic || !stableCallback) {
            return;
        }
        dataProvider.subscribe(topic, callbackWithUnsubscribe);
        return () => {
            unsubscribeOnUnmount &&
                dataProvider.unsubscribe(topic, callbackWithUnsubscribe);
        };
    }, [
        enabled,
        dataProvider,
        topic,
        stableCallback,
        callbackWithUnsubscribe,
        unsubscribeOnUnmount,
    ]);
};
