import { useCallback } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { useAuthenticated, useGetOne, useGetRecordRepresentation, useGetResourceLabel, useMutationMiddlewares, useNotify, useParams, useRedirect, useRefresh, useResourceContext, useTranslate, useUpdate, } from 'react-admin';
import { useTreeContext } from './useTreeContext';
/**
 * Prepare data for the Edit view.
 *
 * useEditNodeController does a few things:
 * - it grabs the id from the URL and the resource name from the ResourceContext,
 * - it fetches the record via useGetOne,
 * - it prepares the page title.
 *
 * @param {Object} props The props passed to the EditNode component.
 *
 * @return {Object} controllerProps Fetched data and callbacks for the Edit view
 *
 * @example
 *
 * import { useEditNodeController } from '@react-admin/ra-tree';
 * import EditView from './EditView';
 *
 * const MyEdit = () => {
 *     const controllerProps = useEditNodeController({ resource: 'posts', id: 123 });
 *     return <EditView {...controllerProps} {...props} />;
 * }
 */
export const useEditNodeController = (props = {}) => {
    const { disableAuthentication, id: propsId, mutationMode = 'undoable', mutationOptions = {}, queryOptions = {}, redirect: redirectTo = DefaultRedirect, transform, } = props;
    useAuthenticated({ enabled: !disableAuthentication });
    const resource = useResourceContext(props);
    if (resource == null) {
        throw new Error('The useEditNodeController hook must be used inside a ResourceContext or must be passed a resource prop.');
    }
    const getRecordRepresentation = useGetRecordRepresentation(resource);
    const translate = useTranslate();
    const notify = useNotify();
    const redirect = useRedirect();
    const refresh = useRefresh();
    const queryClient = useQueryClient();
    const { lazy, setFinalData } = useTreeContext();
    const { id: routeId } = useParams();
    if (!routeId && !propsId) {
        throw new Error('useEditNodeController requires an id prop or a route with an /:id? parameter.');
    }
    const id = propsId || routeId;
    const { meta: queryMeta, ...otherQueryOptions } = queryOptions;
    const { onSuccess, onError, meta: mutationMeta, ...otherMutationOptions } = mutationOptions;
    const { registerMutationMiddleware, getMutateWithMiddlewares, unregisterMutationMiddleware, } = useMutationMiddlewares();
    const { data: record, error, isLoading, isFetching, isPending, refetch, } = useGetOne(resource, { id, meta: queryMeta }, {
        onError: () => {
            notify('ra.notification.item_doesnt_exist', {
                type: 'warning',
            });
            redirect('list', resource);
            refresh();
        },
        refetchOnReconnect: false,
        refetchOnWindowFocus: false,
        retry: false,
        ...otherQueryOptions,
    });
    // eslint-disable-next-line eqeqeq
    if (record && record.id && record.id != id) {
        throw new Error(`useEditNodeController: Fetched record's id attribute (${record.id}) must match the requested 'id' (${id})`);
    }
    if (lazy && mutationMode === 'undoable') {
        throw new Error(`useEditNodeController: lazy mode is not compatible with mutationMode 'undoable'. Please change to 'pessimistic' or 'optimistic'.`);
    }
    const getResourceLabel = useGetResourceLabel();
    const recordRepresentation = getRecordRepresentation(record);
    const defaultTitle = translate('ra.page.edit', {
        name: getResourceLabel(resource, 1),
        id,
        record,
        recordRepresentation: typeof recordRepresentation === 'string'
            ? recordRepresentation
            : '',
    });
    const recordCached = { id, previousData: record };
    const [update, { isPending: saving }] = useUpdate(resource, recordCached, {
        ...otherMutationOptions,
        mutationMode,
        returnPromise: mutationMode === 'pessimistic',
        getMutateWithMiddlewares,
    });
    const save = useCallback((data, { onSuccess: onSuccessFromSave, onError: onErrorFromSave, transform: transformFromSave, } = {}) => Promise.resolve(transformFromSave
        ? transformFromSave(data, {
            previousData: recordCached.previousData,
        })
        : transform
            ? transform(data, {
                previousData: recordCached.previousData,
            })
            : data).then((data) => {
        return update(resource, { id, data, meta: mutationMeta }, {
            onSuccess: async (newData, variables, context) => {
                // TODO: remove when react-admin v4.1.3 is released
                const updatedData = { ...newData, ...data };
                // hack: only way to tell react-query not to fetch this query for the next 5 seconds
                // because setQueryData doesn't accept a stale time option
                const now = Date.now();
                const updatedAt = mutationMode === 'undoable'
                    ? now + 5 * 1000
                    : now;
                const updateColl = (old) => {
                    if (!old)
                        return old;
                    const index = old.findIndex(
                    // eslint-disable-next-line eqeqeq
                    record => record.id == id);
                    if (index === -1) {
                        return old;
                    }
                    const result = [
                        ...old.slice(0, index),
                        { ...old[index], ...updatedData },
                        ...old.slice(index + 1),
                    ];
                    return result;
                };
                queryClient.setQueryData([resource, 'getOne', { id: String(id) }], (record) => ({
                    ...record,
                    ...updatedData,
                }), { updatedAt });
                queryClient.setQueriesData({
                    queryKey: [resource, 'getList'],
                }, (res) => res && res.data
                    ? {
                        data: updateColl(res.data),
                        total: res.total,
                    }
                    : res, { updatedAt });
                queryClient.setQueriesData({
                    queryKey: [resource, 'getTree'],
                }, (coll) => coll && coll.length
                    ? updateColl(coll)
                    : coll, { updatedAt });
                queryClient.setQueriesData({
                    queryKey: [resource, 'getRootNodes'],
                }, (coll) => coll && coll.length
                    ? updateColl(coll)
                    : coll, { updatedAt });
                queryClient.setQueriesData({
                    queryKey: [resource, 'getMany'],
                }, (coll) => coll && coll.length > 0
                    ? updateColl(coll)
                    : coll, { updatedAt });
                queryClient.setQueriesData({
                    queryKey: [resource, 'getManyReference'],
                }, (res) => res && res.data
                    ? {
                        data: updateColl(res.data),
                        total: res.total,
                    }
                    : res, { updatedAt });
                // In lazy mode we can't rely on react-query to update the tree
                // so we need to update the internal state manually
                if (lazy && setFinalData) {
                    setFinalData(updateColl);
                }
                if (onSuccessFromSave) {
                    return onSuccessFromSave(newData, variables, context);
                }
                if (onSuccess) {
                    return onSuccess(newData, variables, context);
                }
                notify('ra.notification.updated', {
                    type: 'info',
                    messageArgs: { smart_count: 1 },
                    undoable: mutationMode === 'undoable',
                });
                redirect(redirectTo, resource, newData.id, newData);
            },
            onError: onErrorFromSave
                ? onErrorFromSave
                : onError
                    ? onError
                    : (error) => {
                        notify(typeof error === 'string'
                            ? error
                            : error.message ||
                                'ra.notification.http_error', {
                            type: 'warning',
                            messageArgs: {
                                _: typeof error === 'string'
                                    ? error
                                    : error && error.message
                                        ? error.message
                                        : undefined,
                            },
                        });
                    },
        });
    }), [
        id,
        mutationMode,
        mutationMeta,
        notify,
        onError,
        onSuccess,
        queryClient,
        recordCached.previousData,
        redirect,
        redirectTo,
        resource,
        transform,
        update,
        lazy,
        setFinalData,
    ]);
    return {
        defaultTitle,
        error,
        isFetching,
        isLoading,
        isPending,
        mutationMode,
        record,
        redirect: DefaultRedirect,
        refetch,
        registerMutationMiddleware,
        resource,
        save,
        saving,
        unregisterMutationMiddleware,
    };
};
const DefaultRedirect = 'list';
