import { deleteBranchByDeletingAllChildren } from './deleteBranchByDeletingAllChildren';
import { deleteBranchByDeletingNode } from './deleteBranchByDeletingNode';
/**
 * Provided the records contain an array of children ids,
 * augment a dataProvider by adding the Tree methods (getTree, getRootNodes, etc).
 *
 * These methods will call regular dataProvider methods (getList, getOne, update).
 *
 * @warning Do not use in production.
 *
 * The added Tree methods call the API way too much, sometimes asking for the
 * entire tree. In practice, you should implement an optimized API route for
 * each of the Tree methods.
 *
 * @example // Compatible APIs should return records like
 * {
 *     id: 1234,
 *     name: 'hello',
 *     isRoot: false,
 *     children: [45, 356, 1],
 * }
 *
 * @param {DataProvider} dataProvider The dataProvider to augment
 * @param {string} childrenField The name of the field containing the children ids. Defaults to 'children'
 * @param {string} isRootField The name of the field containing the root status. Defaults to 'isRoot'
 * @param {boolean} apiSupportBranchDeletion Indicates whether the API will handle children deletion when deleting a node as well as the parent update. If false, the dataProvider will handle it by making multiple requests in the right order. Defaults to `false`.
 */
export const addTreeMethodsBasedOnChildren = (dataProvider, childrenField = 'children', isRootField = 'isRoot', apiSupportBranchDeletion = false) => {
    const deleteBranch = apiSupportBranchDeletion
        ? deleteBranchByDeletingNode
        : deleteBranchByDeletingAllChildren;
    const treeDataProvider = {
        ...dataProvider,
        getTree: async (resource, params) => {
            const { data } = await dataProvider.getList(resource, {
                filter: params?.filter,
                sort: { field: 'id', order: 'ASC' },
                pagination: { page: 1, perPage: 1000 },
                meta: params?.meta,
            });
            return {
                data,
            };
        },
        getRootNodes: async (resource, params) => {
            const { data } = await dataProvider.getList(resource, {
                filter: { ...params?.filter, [isRootField]: true },
                sort: { field: 'id', order: 'ASC' },
                pagination: { page: 1, perPage: 1000 },
                meta: params?.meta,
            });
            return {
                data: data,
            };
        },
        getParentNode: async (resource, { childId, meta }) => {
            const { data: tree } = await treeDataProvider.getTree(resource, { meta });
            const parent = tree.find(node => node[childrenField].includes(childId));
            return {
                data: parent,
            };
        },
        getChildNodes: async (resource, { parentId, meta }) => {
            // get element
            const { data: parent } = await dataProvider.getOne(resource, {
                id: parentId,
                meta,
            });
            // get child records
            const { data } = await dataProvider.getList(resource, {
                filter: { id: parent[childrenField] },
                sort: { field: 'id', order: 'ASC' },
                pagination: { page: 1, perPage: 1000 },
                meta,
            });
            const children = parent[childrenField]
                .map(id => data.find(record => record.id === id))
                .filter(record => !!record);
            return {
                data: children,
            };
        },
        moveAsNthChildOf: async (resource, { source, destination, position, meta }) => {
            // 1. Fetch entire tree to find source and destination parent
            const { data: nodes } = await dataProvider.getList(resource, {
                filter: {},
                sort: { field: 'id', order: 'ASC' },
                pagination: { page: 1, perPage: 1000 },
                meta,
            });
            // 2. Find source parent
            // we need the entire tree client-side for that because it's unlikely that the API provides search inside children
            const sourceParent = nodes
                .filter(node => node[childrenField].includes(source.id))
                .pop();
            // 3. Remove source from sourceParent children if the node has one
            if (sourceParent) {
                await dataProvider.update(resource, {
                    id: sourceParent.id,
                    data: {
                        [childrenField]: sourceParent[childrenField].filter(childId => childId !== source.id),
                    },
                    previousData: sourceParent,
                    meta,
                });
            }
            // 3.bis. If source parent is destination we need to apply changes to
            // destination before continuing
            if (sourceParent && sourceParent.id === destination.id) {
                destination = {
                    ...destination,
                    [childrenField]: sourceParent[childrenField].filter(childId => childId !== source.id),
                };
            }
            // 4. Add source in destinationParent children
            if (position === 0 || position === -1) {
                await dataProvider.update(resource, {
                    id: destination.id,
                    data: {
                        [childrenField]: [].concat(source.id, destination[childrenField]),
                    },
                    previousData: destination,
                    meta,
                });
            }
            else {
                const children = [].concat(destination[childrenField].slice(0, position), source.id, destination[childrenField].slice(position));
                await dataProvider.update(resource, {
                    id: destination.id,
                    data: {
                        [childrenField]: children,
                    },
                    previousData: destination,
                    meta,
                });
            }
            return { data: undefined };
        },
        moveAsNthSiblingOf: async (resource, { source, destination, position, meta }) => {
            // 1. Fetch entire tree to find source and destination parent
            const { data: nodes } = await dataProvider.getList(resource, {
                filter: {},
                sort: { field: 'id', order: 'ASC' },
                pagination: { page: 1, perPage: 1000 },
                meta,
            });
            // 2. Find source and destination parent
            // we need the entire tree client-side for that because it's unlikely that the API provides search inside children
            const sourceParent = nodes
                .filter(node => node[childrenField].includes(source.id))
                .pop();
            const destinationParent = nodes
                .filter(node => node[childrenField].includes(destination.id))
                .pop();
            if (sourceParent &&
                destinationParent &&
                sourceParent.id === destinationParent.id) {
                // 3. Move child to another position in the same parent
                const children = [...destinationParent[childrenField]];
                const sourcePosition = children.indexOf(source.id);
                let destinationPosition = sourcePosition > children.indexOf(destination.id)
                    ? children.indexOf(destination.id) + 1
                    : children.indexOf(destination.id);
                if (position === -1) {
                    destinationPosition--;
                }
                children.splice(destinationPosition, 0, children.splice(children.indexOf(source.id), 1)[0]);
                await dataProvider.update(resource, {
                    id: destinationParent.id,
                    data: {
                        [childrenField]: children,
                    },
                    previousData: destinationParent,
                    meta,
                });
            }
            else {
                // 3. Remove source from sourceParent children if the node has one
                if (sourceParent) {
                    await dataProvider.update(resource, {
                        id: sourceParent.id,
                        data: {
                            [childrenField]: sourceParent[childrenField].filter(childId => childId !== source.id),
                        },
                        previousData: sourceParent,
                        meta,
                    });
                }
                let destinationPosition = position;
                if (position === -1) {
                    destinationPosition = 0;
                }
                // 4. Add source in destinationParent children
                if (destinationParent) {
                    await dataProvider.update(resource, {
                        id: destinationParent.id,
                        data: {
                            [childrenField]: destinationParent[childrenField]
                                .slice(0, destinationPosition)
                                .concat(source.id, destinationParent[childrenField].slice(destinationPosition)),
                        },
                        previousData: destinationParent,
                        meta,
                    });
                }
            }
            return { data: undefined };
        },
        addRootNode: async (resource, { data, meta }) => dataProvider.create(resource, {
            data: {
                ...data,
                [isRootField]: true,
                [childrenField]: [],
            },
            meta,
        }),
        addChildNode: async (resource, { parentId, data, meta, position }) => {
            // get Parent
            const { data: parent } = await dataProvider.getOne(resource, {
                id: parentId,
                meta,
            });
            // create child
            const newChild = await dataProvider.create(resource, {
                data: {
                    ...data,
                    [isRootField]: false,
                    [childrenField]: [],
                },
                meta,
            });
            // update parent children
            await dataProvider.update(resource, {
                id: parentId,
                data: {
                    ...parent,
                    children: position !== undefined &&
                        Number.isInteger(position) &&
                        position >= 0 &&
                        position <= parent[childrenField].length
                        ? [
                            ...parent[childrenField].slice(0, position),
                            newChild.data.id,
                            ...parent[childrenField].slice(position),
                        ]
                        : [...parent[childrenField], newChild.data.id],
                },
                previousData: parent,
                meta,
            });
            return newChild;
        },
        deleteBranch: async (resource, params) => {
            const { id, data, meta } = params;
            // Deletion of the record itself must be handled by specialized method.
            await deleteBranch(treeDataProvider, resource, params);
            // However, we must update the parent if the node has one
            // get Parent
            const { data: parent } = await treeDataProvider.getParentNode(resource, {
                childId: id,
                meta,
            });
            if (parent) {
                await dataProvider.update(resource, {
                    id: parent.id,
                    data: {
                        ...parent,
                        children: parent[childrenField].filter(childId => childId !== id),
                    },
                    previousData: parent,
                    meta,
                });
            }
            return { data };
        },
    };
    return treeDataProvider;
};
