import { useContext, useMemo } from 'react';
import { TreeContext } from './TreeContext';
/**
 * A hook which returns the TreeController data and handlers.
 * @param props Props matching the TreeController data and handlers that will be returned instead of the ones from context.
 * @returns The TreeController data and handlers
 */
export const useTreeContext = (props) => {
    const context = useContext(TreeContext);
    const contextMergedWithProps = useMemo(() => ({
        data: props?.data ?? context?.data,
        defaultTitle: props?.defaultTitle ?? context?.defaultTitle,
        error: props?.error ?? context?.error,
        expandedKeys: props?.expandedKeys ?? context?.expandedKeys,
        handleAddNode: props?.handleAddNode ?? context?.handleAddNode,
        handleDrop: props?.handleDrop ?? context?.handleDrop,
        handleExpand: props?.handleExpand ?? context?.handleExpand,
        isFetching: props?.isFetching ?? context?.isFetching,
        isLoading: props?.isLoading ?? context?.isLoading,
        loadChildNodes: props?.loadChildNodes ?? context?.loadChildNodes,
        newNode: props?.newNode ?? context?.newNode,
        lazy: props?.lazy ?? context?.lazy,
        setFinalData: props?.setFinalData ?? context?.setFinalData,
    }), [props, context]);
    return contextMergedWithProps;
};
