import { useEvent, useRecordContext, useResourceContext, useTranslate, } from 'ra-core';
import { detectChangedFields } from './utils';
export const useGenerateChangeMessage = (props = {}) => {
    const recordFromContext = useRecordContext(props);
    const resourceFromContext = useResourceContext(props);
    const translate = useTranslate();
    return useEvent(({ data, record = recordFromContext, resource = resourceFromContext, }) => {
        const changedFields = detectChangedFields(data, record);
        if (changedFields.length === 0) {
            if (!record || record.id === undefined) {
                return translate('ra-history.on_save.initial_changes', {
                    _: 'Initial revision',
                });
            }
            else {
                return translate('ra-history.on_save.no_changes', {
                    _: 'No changes',
                });
            }
        }
        if (changedFields.length === 1) {
            return translate('ra-history.on_save.one_change', {
                _: 'Changed %{field}',
                field: translate(`resources.${resource}.fields.${changedFields[0]}`, { _: changedFields[0] }),
            });
        }
        const modifiedFields = changedFields.map(field => translate(`resources.${resource}.fields.${field}`, { _: field }));
        return translate('ra-history.on_save.many_changes', {
            _: 'Changed %{fields}',
            fields: modifiedFields.join(', '),
        });
    });
};
