import { useTranslate } from 'ra-core';
import { useLockCallbacks, } from './controller';
export const LockStatusBase = (props) => {
    const { render } = props;
    const lockCallbacksProps = useLockCallbacks(props);
    const { lock, isLocked, isLockedByCurrentUser, isLocking } = lockCallbacksProps;
    const translate = useTranslate();
    const lockedByYouMessage = translate('ra-realtime.locks.status.locked_by_you', { _: 'Locked by you, click to unlock' });
    const lockedByAnotherUserMessage = translate('ra-realtime.locks.status.locked_by_another_user', { identity: lock?.identity, _: 'Locked by another user: %{identity}' });
    const unlockedMessage = translate('ra-realtime.locks.status.unlocked', {
        _: 'Record is unlocked, click to lock',
    });
    return render({
        ...lockCallbacksProps,
        isLocking,
        lockStatus: isLocked
            ? isLockedByCurrentUser
                ? 'lockedByUser'
                : 'lockedByAnotherUser'
            : 'unlocked',
        message: isLocked
            ? isLockedByCurrentUser
                ? lockedByYouMessage
                : lockedByAnotherUserMessage
            : unlockedMessage,
    });
};
