import { useDataProvider, useEvent } from 'react-admin';
import { useQuery, useQueryClient, } from '@tanstack/react-query';
import { useEffect } from 'react';
/**
 * Call the dataProvider.getRootNodes() method and return the resolved value
 * as well as the loading state.
 *
 * The return value updates according to the request state:
 *
 * - start: { isLoading: true, refetch }
 * - success: { data: [data from store], total: [total from response], isLoading: false, refetch }
 * - error: { error: [error from response], isLoading: false, refetch }
 *
 * This hook will return the cached result when called a second time
 * with the same parameters, until the response arrives.
 *
 * @param {string} resource The resource name, e.g. 'posts'
 * @param {Params} params The getTree parameters { meta }
 * @param {Object} options Options object to pass to the queryClient.
 * May include side effects to be executed upon success or failure, e.g. { onSuccess: () => { refresh(); } }
 *
 * @typedef Params
 * @prop params.meta Optional meta parameters
 *
 * @returns The current request state. Destructure as { data, error, isLoading, isFetching }.
 *
 * @example // usage
 *
 * import { useGetRootNodes } from '@react-admin/ra-tree';
 *
 * const Categories = () => {
 *     const { data: tree, isLoading, error } = useGetRootNodes('categories');
 *     if (isLoading) { return <Loading />; }
 *     if (error) { return <p>ERROR</p>; }
 *     return <Tree tree={data} />;
 * };
 */
export const useGetRootNodes = (resource, params = {}, options) => {
    const dataProvider = useDataProvider();
    const queryClient = useQueryClient();
    const { meta } = params;
    const { onSuccess, onError, onSettled, ...restOptions } = options ?? {};
    const result = useQuery({
        queryKey: [resource, 'getRootNodes', params],
        queryFn: () => dataProvider
            .getRootNodes(resource, params)
            .then(({ data }) => data),
        ...restOptions,
    });
    const onSuccessEvent = useEvent(onSuccess ?? (() => undefined));
    const onErrorEvent = useEvent(onError ?? (() => undefined));
    const onSettledEvent = useEvent(onSettled ?? (() => undefined));
    useEffect(() => {
        if (result.data === undefined ||
            result.error != null ||
            result.isFetching)
            return;
        onSuccessEvent(result.data);
    }, [onSuccessEvent, result.data, result.error, result.isFetching]);
    useEffect(() => {
        if (result.error == null || result.isFetching)
            return;
        onErrorEvent(result.error);
    }, [onErrorEvent, result.error, result.isFetching]);
    useEffect(() => {
        if (result.status === 'pending' || result.isFetching)
            return;
        onSettledEvent(result.data, result.error);
    }, [
        onSettledEvent,
        result.data,
        result.error,
        result.isFetching,
        result.status,
    ]);
    useEffect(() => {
        if (!result.data)
            return;
        result.data.forEach(record => {
            if (record.children) {
                record.children.forEach(childId => {
                    queryClient.setQueryData([resource, 'getParentNode', { childId, meta }], oldRecord => oldRecord ?? record);
                });
            }
        });
    }, [meta, queryClient, resource, result.data]);
    return result;
};
