import { useQuery, } from '@tanstack/react-query';
import { useDataProvider } from 'ra-core';
/**
 * Call the dataProvider.getLock() method and return the resolved lock if it exists,
 * as well as the loading state.
 *
 * @param {string} resource
 * @param {GetLockParams} params The getLock parameters { id, meta }
 * @param {Object} options React Query Options object
 *
 * @returns The current lock state. Destructure as { data, error, isPending, isFetching }.
 *
 * @example Simple Usage
 *
 * ```tsx
 * const { data } = useGetLock('posts', { id: 123 });
 * ```
 *
 * @example Getting resource and recordId from context
 *
 * ```tsx
 * const resource = useResourceContext();
 * const id = useGetRecordId();
 * const { data: lock } = useGetLock(resource, { id });
 * ```
 *
 * @example Custom toolbar
 *
 * ```tsx
 * const CustomToolbar = () => {
 *     const resource = useResourceContext();
 *     const id = useGetRecordId();
 *     const { isPending: loading, data: lock } = useGetLock(resource, { id });
 *
 *     const isMarioLocker = lock?.identity === 'mario';
 *
 *     return (
 *         <Toolbar>
 *             <SaveButton disabled={loading || !isMarioLocker} />
 *             {!lock?.identity ? null : isMarioLocker ? (
 *                 <LockMessage>{`You're locking this record`}</LockMessage>
 *             ) : (
 *                 <LockMessage>
 *                     {`This record is locked by another inhabitant of the mushroom kingdom: ${lock?.identity}.`}
 *                 </LockMessage>
 *             )}
 *         </Toolbar>
 *     );
 * };
 * ```
 *
 */
export function useGetLock(resource, params, options = {}) {
    const dataProvider = useDataProvider();
    return useQuery({
        queryKey: [resource, 'getLock', params],
        queryFn: async () => dataProvider
            .getLock(resource, params)
            // Queries must return a value or null, but never undefined
            .then(({ data }) => data ?? null),
        ...options,
    });
}
