import * as React from 'react';
import { useListFilterContext } from 'react-admin';
/**
 * Keeps a range input's `${source}_gte` / `${source}_lte` filter pair in sync
 * with the input's visibility.
 *
 * A range input declares e.g. `source="date"` but stores its values in
 * `date_gte` and `date_lte`. React-admin's filter form only auto-shows an
 * input when `displayedFilters[source]` is set or `filterValues[source]` is
 * non-empty, so the gte/lte pair can end up applied without the matching
 * input being visible. This hook reconciles both directions:
 *
 *   - On mount, if the range values are present but the input is hidden
 *     (typically from a shared or bookmarked URL), the input is revealed so
 *     the user can see and edit the active range.
 *   - When the user hides the input after it was shown, the range values are
 *     cleared so the list no longer filters by an invisible criterion.
 *
 * Must be called inside a `ListContext` (typically within a `<List>`'s filter).
 *
 * @param source The source of the range filter.
 *
 * @example
 * const EventListFilter = (props) => {
 *     useWatchRangeInputVisibility('date');
 *     return (
 *         <Filter {...props}>
 *             <EventDateInput source="date" />
 *         </Filter>
 *     );
 * };
 */
export const useWatchRangeInputVisibility = (source) => {
    const { displayedFilters, filterValues, setFilters, showFilter } = useListFilterContext();
    const isDisplayed = !!displayedFilters[source];
    const gteKey = `${source}_gte`;
    const lteKey = `${source}_lte`;
    // `null` marks the first run so we can distinguish mount from a hide transition.
    const wasDisplayed = React.useRef(null);
    React.useEffect(() => {
        const previouslyDisplayed = wasDisplayed.current;
        wasDisplayed.current = isDisplayed;
        if (isDisplayed)
            return;
        const hasRangeValue = filterValues[gteKey] != null || filterValues[lteKey] != null;
        if (previouslyDisplayed === true) {
            if (hasRangeValue) {
                setFilters({
                    ...filterValues,
                    [gteKey]: null,
                    [lteKey]: null,
                });
            }
            return;
        }
        if (previouslyDisplayed === null && hasRangeValue) {
            showFilter(source, undefined);
        }
    }, [
        isDisplayed,
        source,
        gteKey,
        lteKey,
        filterValues,
        setFilters,
        showFilter,
    ]);
};
