import { useResourceContext } from 'ra-core';
import { useSubscribe } from './useSubscribe';
/**
 * Hook to subscribe to the events for a record list
 * on mount (and unsubscribe on unmount).
 *
 * @param {SubscriptionCallback<RecordEvent>} subscriptionCallback the callback to be executed when an event is published concerning the resource
 * @param {string} resource optional if used inside a ResourceContextProvider
 * @param {UseSubscribeOptions} options Options object
 *
 * @example // Auto-Updated PostList
 *
 * ```tsx
 * import { ListBase, useNotify, useRefresh } from 'ra-core';
 * import { useSubscribeToRecordList } from '@react-admin/ra-core-ee';
 *
 * const PostList = () => {
 *     const notify = useNotify();
 *     const refresh = useRefresh();
 *     useSubscribeToRecordList(() => {
 *         refresh();
 *         notify('list updated server-side');
 *     });
 *     return (
 *         <ListBase>
 *             ... list view
 *         </ListBase>
 *     );
 * };
 * ```
 *
 * @example // Providing resource manually
 *
 * ```tsx
 * import { ListBase, useNotify, useRefresh } from 'ra-core';
 * import { useSubscribeToRecordList } from '@react-admin/ra-core-ee';
 *
 * const PostList = () => {
 *     const notify = useNotify();
 *     const refresh = useRefresh();
 *     useSubscribeToRecordList(() => {
 *         refresh();
 *         notify('list updated server-side');
 *     }, 'posts');
 *     return (
 *         <ListBase>
 *             ... list view
 *         </ListBase>
 *     );
 * };
 * ```
 */
export const useSubscribeToRecordList = (subscriptionCallback, resource, options) => {
    const actualResource = useResourceContext({ resource });
    const topic = actualResource ? `resource/${actualResource}` : null;
    // if no resource, the topic will be empty and the subscription will be a no-op
    useSubscribe(topic, subscriptionCallback, options);
};
