import { useCreatePath, useResourceDefinitions } from 'react-admin';
const DeleteActions = ['delete', 'deleteMany', 'deleteBranch'];
/**
 * Returns a function which computes the path for a record targetted by an Event if possible.
 *
 * @returns {GetActionLink} A function which returns the path for a record targetted by an Event or undefined.
 * It accepts the record and an optional link type (either 'edit' or 'show').
 * If the link type is not provided, it will return a path to the record edit view if possible or show view otherwise.
 * If the Resource has no edit nor show view, the function returns undefined.
 *
 * @example
 * const EventList = (props) => {
 *     const getActionLink = useGetActionLink();
 *
 *     return (
 *         <List {...props}>
 *             <DataTable rowClick={(id, basePath, record) => getActionLink(record)}>
 *                 ...
 *             </DataTable>
 *         </List>
 *     );
 */
export const useGetActionLink = () => {
    const resources = useResourceDefinitions();
    const createPath = useCreatePath();
    return (record, linkType) => {
        const resource = resources[record.resource];
        // When a user logs out, resources are not available anymore.
        if (!resource) {
            return undefined;
        }
        const hasEditOrShow = resource.hasEdit || resource.hasShow;
        const recordId = record.payload.id || record.payload.data?.id;
        const isLinkable = record.resource &&
            resource &&
            recordId &&
            !DeleteActions.includes(record.action) &&
            hasEditOrShow;
        if (isLinkable) {
            if (resource) {
                const inferredLinkType = resource.hasEdit ? 'edit' : 'show';
                return createPath({
                    resource: record.resource,
                    id: recordId,
                    type: linkType || inferredLinkType,
                });
            }
        }
        return undefined;
    };
};
