export const focusFirstInput = (root, selector) => {
    const observer = new MutationObserver(() => {
        // Some APIs may returns identifiers with slashes (API Platform for instance). We need to escape them to have valid CSS selectors
        const sanitizedSelector = selector.replace(/\//g, '\\/');
        // once the row is replaced by a form, focus the first non-disabled input
        // [role="combobox"] targets MUI Select
        const input = root.querySelectorAll(`${sanitizedSelector} input:not([disabled]):not([readonly]), ${sanitizedSelector} [role="combobox"]:not([disabled]):not([readonly]), ${sanitizedSelector} textarea:not([disabled]):not([readonly])`)[0];
        if (input) {
            observer.disconnect();
            if (input) {
                // If the input supports selection (text inputs for instance), we select the text to make it easier to replace
                if (input.select) {
                    input.select();
                }
                else if (input.focus) {
                    input.focus();
                }
            }
        }
    });
    observer.observe(root, {
        subtree: true,
        childList: true,
    });
    return observer;
};
