import getRCTreeDatum from './getRCTreeDatum';
import getRecordTree from './getRecordTree';
export const getRCTree = (data, titleField, newNodeTitle = 'new node', hideRootNodes = false) => {
    const rcData = data.map(treeRecord => getRCTreeDatum(treeRecord, titleField, newNodeTitle));
    const recordTree = getRecordTree(rcData);
    return hideRootNodes
        ? recordTree.flatMap(rootNode => rootNode.children ?? [])
        : recordTree;
};
