import { useRef } from 'react';
import { useMutation, useQueryClient, } from '@tanstack/react-query';
import { useDataProvider } from 'react-admin';
/**
 * Get a callback to call the dataProvider.addChildNode() method, the result and the loading state.
 *
 * @param {string} resource
 * @param {Params} params The addChildNode parameters { data }
 * @param {Object} options Options object to pass to the queryClient.
 * May include side effects to be executed upon success or failure, e.g. { onSuccess: () => { refresh(); } }
 *
 * @typedef Params
 * @prop params.data The record to add as a child node, e.g. { title: 'hello, world' }
 * @prop params.parentId The identifier of the parent node, e.g. 123
 *
 * @returns The current mutation state. Destructure as [addChildNode, { data, error, isLoading }].
 *
 * The return value updates according to the request state:
 *
 * - initial: [addChildNode, { isLoading: false, isIdle: true }]
 * - start:   [addChildNode, { isLoading: true }]
 * - success: [addChildNode, { data: [data from response], isLoading: false, isSuccess: true }]
 * - error:   [addChildNode, { error: [error from response], isLoading: false, isError: true }]
 *
 * The addChildNode() function must be called with a resource and a parameter object: addChildNode(resource, { data, meta }, options)
 *
 * This hook uses react-query useMutation under the hood.
 * This means the state object contains mutate, isIdle, reset and other react-query methods.
 *
 * @see https://react-query.tanstack.com/reference/useMutation
 *
 * @example // set params when calling the addChildNode callback
 *
 * import { useAddChildNode } from '@react-admin/ra-tree';
 *
 * const AddNodeButton = ({ record }) => {
 *     const node = { title: 'a child node', parentId: record.id };
 *     const [addChildNode, { isLoading, error }] = useAddChildNode();
 *     const handleClick = () => {
 *         addChildNode('nodes', { data: node })
 *     }
 *     if (error) { return <p>ERROR</p>; }
 *     return <button disabled={isLoading} onClick={() => addChildNode()}>Add a new child node</button>;
 * };
 *
 * @example // set params when calling the hook
 *
 * import { useAddChildNode } from '@react-admin/ra-tree';
 *
 * const AddNodeButton = ({ record }) => {
 *     const node = { title: 'a child node', parentId: record.id };
 *     const [addChildNode, { isLoading, error }] = useAddChildNode('nodes', { data: node });
 *     if (error) { return <p>ERROR</p>; }
 *     return <button disabled={isLoading} onClick={() => addChildNode()}>Add a new child node</button>;
 * };
 *
 * @example // TypeScript
 * const [addChildNode, { data }] = useAddChildNode<Product>('products', { data: product });
 *                    \-- data is Product
 */
export const useAddChildNode = (resource, params = {}, options = {}) => {
    const dataProvider = useDataProvider();
    const queryClient = useQueryClient();
    const paramsRef = useRef(params);
    const mutation = useMutation({
        mutationFn: ({ resource: callTimeResource = resource, data: callTimeData = paramsRef.current.data, parentId: callTimeParentId = paramsRef.current.parentId, position: callPosition = paramsRef.current.position, meta: callTimeMeta = paramsRef.current.meta, } = {}) => {
            if (!callTimeResource) {
                throw new Error('useAddChildNode mutation requires a non-empty resource');
            }
            if (callTimeData == null) {
                throw new Error('useAddChildNode mutation requires non-empty data');
            }
            if (callTimeParentId == null) {
                throw new Error('useAddChildNode mutation requires a non-empty parent id');
            }
            return dataProvider
                .addChildNode(callTimeResource, {
                data: callTimeData,
                parentId: callTimeParentId,
                position: callPosition,
                meta: callTimeMeta,
            })
                .then(({ data }) => data);
        },
        ...options,
        onSuccess: (data, variables = {}, context) => {
            const { resource: callTimeResource = resource } = variables;
            queryClient.setQueryData([callTimeResource, 'getOne', { id: String(data.id) }], data);
            if (options.onSuccess) {
                options.onSuccess(data, variables, context);
            }
            // call-time success callback is executed by react-query
        },
    });
    const addRootNode = async (callTimeResource = resource, callTimeParams = {}, callTimeOptions = {}) => {
        const { returnPromise, ...otherOptions } = callTimeOptions;
        if (returnPromise) {
            return mutation.mutateAsync({ resource: callTimeResource, ...callTimeParams }, otherOptions);
        }
        mutation.mutate({ resource: callTimeResource, ...callTimeParams }, otherOptions);
    };
    return [addRootNode, mutation];
};
