import { useEffect } from 'react';
import { useHotkeys } from 'react-hotkeys-hook';
/**
 * Hook that allows defining a keyboard shortcut to focus an input.
 *
 * @param {useKeyboardShortcutProps} props
 * - {boolean | Keys} shortcut: Optional. Enable or configure a shortcut to focus the input.
 * - {MutableRefObject<HTMLInputElement | undefined>} inputRef: Optional. Reference of the input you want to focus/blur.
 * - {boolean} isOpen: Optional. A boolean indicating whether the input is currently focused.
 * - {(event: KeyboardEvent) => void} onOpen: Optional. Function to run when the shortcut is detected but the input isn't focused.
 * - {(event: KeyboardEvent) => void} onClose: Optional. Function to run when the shortcut is detected and the input is currently focused.
 *
 * @see SearchInput
 *
 * @example
 *
 *  import React from 'react';
 *  import { useKeyboardShortcut, useSearchController } from '@react-admin/ra-search';
 *  import { CardContent } from '@mui/material';
 *  import { Admin, Layout, Link, Resource } from 'react-admin';
 *  import { dataProvider } from './dataProvider';
 *  import { ArtistsList } from './artists';
 *
 *  const MyDashboard = () => {
 *      const ref = React.useRef<HTMLInputElement>();
 *      useKeyboardShortcut({
 *          shortcut: true,
 *          inputRef: ref,
 *      });
 *      const { searchData, query, doSearch } = useSearchController({});
 *      const onChange = e => doSearch(e.target.value);
 *      return (
 *          <CardContent>
 *              <input type="text" value={query} onChange={onChange} ref={ref} />
 *              {searchData.data?.map(item => (
 *                  <div key={item.id}>
 *                      <Link to={item.url}>
 *                          <strong>{item.content.label}</strong>
 *                      </Link>
 *                      <p>{item.content.description}</p>
 *                  </div>
 *              ))}
 *          </CardContent>
 *      );
 *  };
 *
 *  const App = () => (
 *    <Admin dataProvider={dataProvider} dashboard={MyDashboard}>
 *      <Resource
 *        name="artists"
 *        list={ArtistsList}
 *      />
 *    </Admin>
 *  );
 *
 */
export const useKeyboardShortcut = ({ shortcut = true, inputRef, isFocused, onOpen = keyboardEvent => {
    keyboardEvent.preventDefault();
    inputRef?.current?.focus();
}, onClose, }) => {
    const includesEsc = (Array.isArray(shortcut) &&
        shortcut.some(key => key.includes('esc') || key.includes('Escape'))) ||
        (typeof shortcut === 'string' &&
            (shortcut.includes('esc') || shortcut.includes('Escape')));
    useHotkeys(shortcut === false ? '' : shortcut === true ? 'mod+k' : shortcut, keyboardEvent => {
        if (isFocused
            ? isFocused
            : inputRef?.current === document.activeElement) {
            onClose && onClose(keyboardEvent);
            inputRef?.current?.blur();
            return;
        }
        onOpen(keyboardEvent);
    }, {
        enabled: !!shortcut,
        enableOnFormTags: ['input'],
    });
    useEffect(() => {
        const handleKeyDown = (event) => {
            if (event.code === 'Escape') {
                onClose && onClose(event);
                inputRef?.current?.blur();
            }
        };
        if (includesEsc || !shortcut)
            return;
        document.addEventListener('keydown', handleKeyDown);
        return () => {
            document.removeEventListener('keydown', handleKeyDown);
        };
    }, [onClose, includesEsc, shortcut, inputRef]);
};
