import { useCallback } from 'react';
import { useMutation, useQueryClient, } from '@tanstack/react-query';
import { useDataProvider } from 'ra-core';
import omit from 'lodash/omit';
/**
 * Returns a function allowing to call the dataProvider.unlock() method, as well as
 * the react-query mutation handle.
 *
 * @param {string} resource
 * @param {UnlockParams} params The unlock function parameters { id, identity, meta }
 * @param {Object} options React Query Mutation Options object
 *
 * @returns The `unlock()` callback as well as the react-query mutation object.
 *
 * @example Simple Usage
 *
 * ```tsx
 * const [unlock, _mutation] = useUnlock('posts', { id: 123, identity: 'mario' });
 * React.useEffect(() => {
 *     unlock();
 * }, []);
 * ```
 *
 * @example Call unlock with parameters
 *
 * ```tsx
 * const [unlock, _mutation] = useUnlock();
 * React.useEffect(() => {
 *     unlock('posts', { id: 123, identity: 'mario' });
 * }, []);
 * ```
 */
export function useUnlock(resource, params, options = {}) {
    const dataProvider = useDataProvider();
    const queryClient = useQueryClient();
    const updateCache = ({ resource, params, }) => {
        const updateColl = (old) => {
            if (!old)
                return;
            const { id: recordId } = params;
            if (!recordId)
                return old;
            const index = old.findIndex(lock => lock.recordId === recordId);
            if (index === -1) {
                return old;
            }
            return [...old.slice(0, index), ...old.slice(index + 1)];
        };
        queryClient.invalidateQueries({
            queryKey: [resource, 'getLock', omit(params, ['identity'])],
        });
        queryClient.setQueriesData({
            queryKey: [
                resource,
                'getLocks',
                omit(params, ['identity', 'id']),
            ],
        }, (res) => (res && res.length ? updateColl(res) : res));
    };
    const mutation = useMutation({
        mutationFn: ({ resource: callTimeResource = resource, params: callTimeParams = params, } = {}) => dataProvider.unlock(callTimeResource, callTimeParams),
        ...options,
        onSuccess: (data, variables, context) => {
            updateCache({
                resource: variables?.resource || resource,
                params: variables?.params || params,
            });
            if (options.onSuccess) {
                options.onSuccess(data, variables, context);
            }
        },
    });
    const unlock = useCallback((callTimeResource = resource, callTimeParams = params, mutateOptions = options) => {
        return mutation.mutate({ resource: callTimeResource, params: callTimeParams }, mutateOptions);
    }, 
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [mutation.mutate, JSON.stringify({ resource, params, options })]);
    return [unlock, mutation];
}
